var flags = System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic;
var method = typeof(SSW.MotionView).GetMethod("Ease", flags);
if (typeof(SSW.MotionView).GetField("_shown", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic) == null) throw new System.Exception("presentation baseline is not compiled");
UnityEngine.Vector2 Ease(UnityEngine.Vector2 offset, UnityEngine.Vector2 velocity, float speed, float delta) => (UnityEngine.Vector2)method.Invoke(null, new object[] { offset, velocity, speed, delta, velocity * delta });
var checks = new System.Collections.Generic.List<string>();
foreach (int fps in new[] { 30, 60, 144 })
{
    float dt = 1f / fps;
    var offset = new UnityEngine.Vector2(-0.7f, 0f);
    var velocity = new UnityEngine.Vector2(-3.5f, 0f);
    for (int i = 0; i < fps; i++)
    {
        var next = Ease(offset, velocity, 3.5f, dt);
        if (velocity.x * dt + next.x - offset.x > 0.00001f) throw new System.Exception("slow reversed at " + fps);
        if (next.sqrMagnitude > offset.sqrMagnitude + 0.00001f) throw new System.Exception("offset grew at " + fps);
        offset = next;
    }
    if (offset.sqrMagnitude > 0.00001f) throw new System.Exception("slow did not settle at " + fps);
    checks.Add("slow stays in direction and settles at " + fps);
    offset = new UnityEngine.Vector2(1.61f, 0f);
    for (int i = 0; i < fps / 4; i++) offset = Ease(offset, new UnityEngine.Vector2(-10.5f, 0f), 10.5f, dt);
    if (offset.sqrMagnitude > 0.00001f) throw new System.Exception("haste did not settle at " + fps);
    checks.Add("haste settles within 250 ms at " + fps);
    if (Ease(UnityEngine.Vector2.zero, velocity, 7f, dt) != UnityEngine.Vector2.zero) throw new System.Exception("zero drift at " + fps);
    checks.Add("zero remains zero at " + fps);
}
var held = (UnityEngine.Vector2)method.Invoke(null, new object[] { new UnityEngine.Vector2(-0.7f, 0f), new UnityEngine.Vector2(-7f, 0f), 7f, 1f/144f, UnityEngine.Vector2.zero });
if (held.x != -0.7f) throw new System.Exception("stationary interpolation frame reversed");
checks.Add("stationary interpolation frame does not reverse");
var before = new UnityEngine.Vector2(-0.7f, 0f);
var movement = new UnityEngine.Vector2(-3.5f/144f, 0f);
var after = (UnityEngine.Vector2)method.Invoke(null, new object[] { before, new UnityEngine.Vector2(-7f, 0f), 7f, 1f/144f, movement });
if ((movement+after-before).x > 0f) throw new System.Exception("slow expiration reversed the view");
checks.Add("slow expiration respects actual interpolation movement");
return checks;

int count = 0;
System.Action<bool, string> check = (ok, name) =>
{
    if (!ok) throw new System.Exception(name);
    count++;
};
var stock = new SSW.CastStock();
stock.Reset(4);
check(stock.Held.Kind == -1 && stock.Next.Kind == -1, "empty");
stock.Add(2, 0, 0.6);
var first = stock.Held;
stock.Add(2, 1.5, 0.6);
var second = stock.Next;
check(first.Id != second.Id && first.Kind == second.Kind, "same kind has distinct ids");
check(!stock.Take(second.Id, 4, 1.6, out _), "reserve cannot skip held");
stock.Add(1, 3, 0.6);
var third = stock.Next;
check(stock.Take(first.Id, 4, 3.5, out int kind) && kind == 2, "delayed replaced stock keeps kind");
check(stock.Held.Id == second.Id && stock.Next.Id == third.Id, "old stock leaves current slots intact");
check(!stock.Take(first.Id, 4, 3.51, out _), "old stock cannot replay");
check(stock.Take(second.Id, 4, 3.66, out kind) && kind == 2, "fast second shot after delayed first");
check(stock.Held.Id == third.Id && stock.Next.Id == 0, "second shot promotes one reserve");
check(!stock.Take(9999, 4, 3.7, out _) && !stock.Take(0, 4, 3.7, out _), "unissued ids rejected");
stock.Add(0, 4, 100);
stock.Add(3, 5, 100);
check(!stock.Take(third.Id, 4, 6.25, out _), "grace capped and expiry exclusive");
var beforeReset = stock.Held;
stock.Reset(5);
check(stock.Held.Kind == beforeReset.Kind && stock.Held.Id != beforeReset.Id, "epoch preserves kind renews id");
check(!stock.Take(beforeReset.Id, 5, 6.3, out _), "old epoch id rejected with new epoch");
check(!stock.Take(stock.Held.Id, 4, 6.3, out _), "old epoch rejected with current id");
check(stock.Take(stock.Held.Id, 5, 6.3, out _), "new epoch current stock accepted");
check(stock.Take(stock.Held.Id, 5, 6.46, out _), "quick second stock accepted");
check(stock.Held.Id == 0 && stock.Next.Id == 0, "both spent empty");
stock.Reset(6);
stock.Add(2, 10, 1.25);
var delayed = stock.Held;
stock.Add(1, 11.5, 1.25);
stock.Add(3, 13, 1.25);
check(stock.Take(delayed.Id, 6, 14.1, out kind) && kind == 2, "RTT spike preserves replaced stock for 1.1 seconds");
check(!stock.Take(delayed.Id, 6, 14.11, out _), "delayed stock still cannot replay");
return count + " stock checks passed";

var previous = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
var scene = UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene, UnityEditor.SceneManagement.NewSceneMode.Additive);
var checks = new System.Collections.Generic.List<string>();
try
{
    var wall = new UnityEngine.GameObject("Query Wall");
    wall.transform.position = new UnityEngine.Vector3(1000,0,0);
    var collider = wall.AddComponent<UnityEngine.BoxCollider2D>();
    collider.size = new UnityEngine.Vector2(1,4);
    var trigger = new UnityEngine.GameObject("Query Trigger");
    trigger.transform.position = new UnityEngine.Vector3(998,0,0);
    trigger.AddComponent<UnityEngine.BoxCollider2D>().isTrigger = true;
    UnityEngine.Physics2D.SyncTransforms();
    UnityEngine.RaycastHit2D hit;
    var size = new UnityEngine.Vector2(0.3813953f,0.4930232f);
    if (!SSW.ShotQuery.Ground(new UnityEngine.Vector2(997,0),new UnityEngine.Vector2(1003,0),size.x*.5f,size,1,out hit) || hit.collider!=collider) throw new System.Exception("capsule and trigger filter");
    checks.Add("capsule and trigger filter");
    float offset = hit.centroid.x-(999.5f-size.x*.5f);
    if (UnityEngine.Mathf.Abs(offset)>0.03f) throw new System.Exception("capsule contact size: " + offset);
    checks.Add("capsule contact size");
    var contact = hit.centroid;
    if (!SSW.ShotQuery.Touches(collider,contact,size.x*.5f,size)) throw new System.Exception("contact retained");
    checks.Add("contact retained");
    wall.transform.position += UnityEngine.Vector3.up*10;
    UnityEngine.Physics2D.SyncTransforms();
    if (SSW.ShotQuery.Touches(collider,contact,size.x*.5f,size)) throw new System.Exception("moved contact released");
    checks.Add("moved contact released");
    wall.transform.position -= UnityEngine.Vector3.up*10;
    collider.enabled=false;
    UnityEngine.Physics2D.SyncTransforms();
    if (SSW.ShotQuery.Touches(collider,contact,size.x*.5f,size)) throw new System.Exception("disabled contact released");
    checks.Add("disabled contact released");
    UnityEngine.Object.DestroyImmediate(wall);
    if (SSW.ShotQuery.Touches(collider,contact,size.x*.5f,size)) throw new System.Exception("destroyed contact released");
    checks.Add("destroyed contact released");
    var flight = new UnityEngine.GameObject("Contact Flight").AddComponent<SSW.ShotSync>();
    var floor = new UnityEngine.GameObject("Contact Floor");
    floor.transform.position = new UnityEngine.Vector3(1000,-1,0);
    var floorShape = floor.AddComponent<UnityEngine.BoxCollider2D>();
    floorShape.size = new UnityEngine.Vector2(10,1);
    UnityEngine.Physics2D.SyncTransforms();
    var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
    void Set(string name, object value) => typeof(SSW.ShotSync).GetField(name,flags).SetValue(flight,value);
    object Get(string name) => typeof(SSW.ShotSync).GetField(name,flags).GetValue(flight);
    void Accept(SSW.ShotPose pose) => typeof(SSW.ShotSync).GetMethod("Accept",flags).Invoke(flight,new object[]{pose,0.5d});
    var stop = new UnityEngine.Vector2(1000,-0.5f+size.y*.5f);
    Set("_pose",new SSW.ShotPose { Velocity=new UnityEngine.Vector2(15,3),Terrain=true });
    Set("_normal",UnityEngine.Vector2.up);
    Set("_stop",stop);
    Set("_contact",floorShape);
    Set("_size",size);
    Set("_radius",size.x*.5f);
    Set("_blockedAt",0d);
    Accept(new SSW.ShotPose { Time=.1d,Position=stop+new UnityEngine.Vector2(-4,.5f),Velocity=new UnityEngine.Vector2(15,2),Terrain=true });
    if (!flight.Blocked) throw new System.Exception("early pose must not release contact");
    checks.Add("early pose must not release contact");
    Accept(new SSW.ShotPose { Time=.2d,Position=stop+new UnityEngine.Vector2(1,.5f),Velocity=new UnityEngine.Vector2(15,2),Terrain=true });
    if (flight.Blocked || !(bool)Get("_released")) throw new System.Exception("passed contact releases without correction pullback");
    checks.Add("passed contact releases without correction pullback");
    Set("_normal",UnityEngine.Vector2.up);
    Set("_contact",floorShape);
    Accept(new SSW.ShotPose { Time=.3d,Position=stop+new UnityEngine.Vector2(-1,0),Velocity=UnityEngine.Vector2.left,Terrain=true,Turn=1 });
    if (flight.Blocked) throw new System.Exception("bounce turn releases contact");
    checks.Add("bounce turn releases contact");
    return new { checks, offset };
}
finally
{
    UnityEditor.SceneManagement.EditorSceneManager.CloseScene(scene,true);
    UnityEngine.SceneManagement.SceneManager.SetActiveScene(previous);
}
